CREATE TABLE "ADAPTITPOC"."IAGENR" 
   ("IAGSTNO" NUMBER(9,0), 
	"IAGCYR" NUMBER(4,0), 
	"IAGQUAL" VARCHAR2(6 BYTE), 
	"IAGRESULT" VARCHAR2(2 BYTE), 
	"IAGPERSTUDY" VARCHAR2(1 BYTE), 
	"IAGDATE" DATE, 
	"IAGQUALNO" NUMBER(2,0), 
	"IAGPRIMARY" VARCHAR2(1 BYTE), 
	"IAGADFSEQ" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY 
   );
   
  CREATE TABLE "ADAPTITPOC"."IAIQAL" 
   ("IAIQUAL" VARCHAR2(6 BYTE) NOT NULL ENABLE, 
	"IAIAPPQUAL" VARCHAR2(2 BYTE) NOT NULL ENABLE, 
	"IAIFAC" NUMBER(4,0), 
	"IAIDESC" VARCHAR2(40 BYTE), 
	"IAIDEPT" NUMBER(4,0), 
	"IAIEXAMGROUP" VARCHAR2(2 BYTE), 
	"IAICYR" NUMBER(4,0) NOT NULL ENABLE, 
	"IAIADFSEQ" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY,
	 CONSTRAINT "IAIKEY" PRIMARY KEY ("IAIQUAL", "IAICYR"));
	 
	 
  CREATE TABLE "ADAPTITPOC"."IAHSUB" 
   ("IAHSTNO" NUMBER(9,0) NOT NULL ENABLE, 
	"IAHCYR" NUMBER(4,0) NOT NULL ENABLE, 
	"IAHSUBJ" VARCHAR2(7 BYTE) NOT NULL ENABLE, 
	"IAHYMARK" NUMBER(4,0), 
	"IAHEMARK" NUMBER(4,0), 
	"IAHFMARK" NUMBER(4,0), 
	"IAHERES" VARCHAR2(2 BYTE), 
	"IAHQUAL" VARCHAR2(6 BYTE), 
	"IAHDATE" DATE, 
	"IAHSUBJNO" NUMBER(2,0) NOT NULL ENABLE, 
	"IAHQUALNO" NUMBER(2,0), 
	"IAHPRIMARY" VARCHAR2(1 BYTE), 
	"IAHADFSEQ" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY,
	 CONSTRAINT "IAHKEY" PRIMARY KEY ("IAHSTNO", "IAHCYR", "IAHSUBJ", "IAHSUBJNO"));
	 
  CREATE TABLE "ADAPTITPOC"."IBQRSC" 
   ("IBQCODE" VARCHAR2(2 BYTE) NOT NULL ENABLE, 
	"IBQNAME" VARCHAR2(30 BYTE) NOT NULL ENABLE, 
	"IBQPASSFAIL" VARCHAR2(1 BYTE) NOT NULL ENABLE, 
	"IBQADFSEQ" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY,
	 CONSTRAINT "IBQKEY" PRIMARY KEY ("IBQCODE"));

  CREATE TABLE "ADAPTITPOC"."IEPQAL" 
   ("IEPSTNO" NUMBER(9,0) NOT NULL ENABLE, 
	"IEPCYR" NUMBER(4,0) NOT NULL ENABLE, 
	"IEPQUAL" VARCHAR2(6 BYTE) NOT NULL ENABLE, 
	"IEPRESULT" VARCHAR2(2 BYTE), 
	"IEPDATE" DATE, 
	"IEPMARK" NUMBER(4,0), 
	"IEPADFSEQ" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY,
	CONSTRAINT "IEPKEY" PRIMARY KEY ("IEPCYR", "IEPSTNO", "IEPQUAL"));

  CREATE TABLE "ADAPTITPOC"."IALSUB" 
   ("IALSUBJ" VARCHAR2(7 BYTE) NOT NULL ENABLE, 
	"IALFAC" NUMBER(4,0), 
	"IALSCHOOLDEPT" NUMBER(4,0), 
	"IALDESC" VARCHAR2(45 BYTE), 
	"IALCYR" NUMBER(4,0) NOT NULL ENABLE, 
	"IEPADFSEQ" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY,
	 CONSTRAINT "IALKEY" PRIMARY KEY ("IALSUBJ", "IALCYR"));

ALTER TABLE ADAPTITPOC"."IAGENR"
ADD CONSTRAINT iagenr_fk
FOREIGN KEY ("IAGCYR","IAGQUAL")
REFERENCES "ADAPTITPOC"."IAIQAL"("IAICYR","IAIQUAL");